{
  "nl": {
    "issue": [
      {
        "text": "质权人对质押财产的保管义务与赔偿责任，以及质押财产面临毁损、灭失或价值明显减少风险时出质人与质权人各自的救济手段",
        "rules": ["c432-1a", "c432-1b", "c432-2-escrow", "c432-2-return", "c433-1", "c433-2"]
      },
      {
        "text": "质权人在质权存续期间未经出质人同意转质，造成质押财产毁损、灭失时的赔偿责任",
        "rules": ["c434"]
      },
      {
        "text": "质权人放弃质权，以及债务人以自己财产出质时放弃质权对其他担保人的影响",
        "rules": ["c435-1", "c435-2", "c435-exc"]
      },
      {
        "text": "质权的实现、质押财产的返还，以及变价款超过或不足债权数额时的归属与清偿",
        "rules": ["c436-1", "c436-2", "c436-3", "c438-1", "c438-2"]
      }
    ],
    "conditions": [
      {
        "text": "存在质权人、出质人与质押财产（质权人占有质押财产）",
        "rules": ["c432-1a", "c432-1b", "c432-2-escrow", "c432-2-return", "c433-1", "c433-2", "c435-1", "c436-1", "c436-2", "c436-3", "c438-1"]
      },
      {
        "text": "因保管不善致使质押财产毁损、灭失",
        "rules": ["c432-1b"]
      },
      {
        "text": "质权人的行为可能使质押财产毁损、灭失",
        "rules": ["c432-2-escrow", "c432-2-return"]
      },
      {
        "text": "因不可归责于质权人的事由可能使质押财产毁损或者价值明显减少，足以危害质权人的权利",
        "rules": ["c433-1", "c433-2"]
      },
      {
        "text": "出质人不提供相应的担保",
        "rules": ["c433-2"]
      },
      {
        "text": "质权存续期间未经出质人同意转质，并造成质押财产毁损、灭失",
        "rules": ["c434"]
      },
      {
        "text": "债务人以自己的财产出质，质权人放弃该质权，且另有其他担保人为该债务提供担保",
        "rules": ["c435-2"]
      },
      {
        "text": "债务人履行债务，或者出质人提前清偿所担保的债权",
        "rules": ["c436-1"]
      },
      {
        "text": "债务人不履行到期债务，或者发生当事人约定的实现质权的情形",
        "rules": ["c436-2"]
      },
      {
        "text": "质押财产被折价或者变卖",
        "rules": ["c436-3"]
      },
      {
        "text": "质押财产折价或者拍卖、变卖后的价款超过债权数额，或者不足清偿债权数额",
        "rules": ["c438-1", "c438-2"]
      }
    ],
    "exceptions": [
      {
        "text": "其他担保人承诺仍然提供担保的，不免除其担保责任（第435条但书）",
        "rules": ["c435-exc"]
      }
    ],
    "effects": [
      {
        "text": "质权人负有妥善保管质押财产的义务；因保管不善致使质押财产毁损、灭失的，应当承担赔偿责任",
        "rules": ["c432-1a", "c432-1b"]
      },
      {
        "text": "出质人可以请求质权人将质押财产提存，或者请求提前清偿债务并返还质押财产",
        "rules": ["c432-2-escrow", "c432-2-return"]
      },
      {
        "text": "质权人有权请求出质人提供相应的担保；出质人不提供的，质权人可以拍卖、变卖质押财产，并与出质人协议将所得价款提前清偿债务或者提存",
        "rules": ["c433-1", "c433-2"]
      },
      {
        "text": "擅自转质造成质押财产毁损、灭失的，质权人应当承担赔偿责任",
        "rules": ["c434"]
      },
      {
        "text": "质权人可以放弃质权；债务人以自己的财产出质而质权人放弃该质权的，其他担保人在质权人丧失优先受偿权益的范围内免除担保责任",
        "rules": ["c435-1", "c435-2"]
      },
      {
        "text": "债务人履行债务或者出质人提前清偿所担保债权的，质权人应当返还质押财产",
        "rules": ["c436-1"]
      },
      {
        "text": "质权人可以与出质人协议以质押财产折价，也可以就拍卖、变卖质押财产所得的价款优先受偿",
        "rules": ["c436-2"]
      },
      {
        "text": "质押财产折价或者变卖的，应当参照市场价格",
        "rules": ["c436-3"]
      },
      {
        "text": "价款超过债权数额的部分归出质人所有，不足部分由债务人清偿",
        "rules": ["c438-1", "c438-2"]
      }
    ],
    "priority": [
      {
        "text": "其他担保人承诺仍然提供担保的，优先于第435条的免责效果，不免除其担保责任",
        "rules": ["c435-exc", "c435-2"]
      }
    ],
    "distinguish": [
      {
        "text": "第432条第2款是出质人在质权人行为可能致质押财产毁损、灭失时的救济（请求提存或提前清偿并返还）；第433条是不可归责于质权人的事由致质押财产有毁损或价值明显减少风险时质权人的权利；第434条是擅自转质的赔偿责任，三者适用前提不同",
        "rules": []
      },
      {
        "text": "LEGO 卡片称“质权放弃不影响主债权本身效力”，法条未明文，属学理说明，未形式化",
        "rules": []
      },
      {
        "text": "笔记体系中的出质人请求质权人及时行使质权（第437条）不在本行挂载法条范围内",
        "rules": []
      }
    ]
  },
